<template>
  <div class="container">
     <Navbar/>
  </div>

  <div class="p-3">
    <div class="mb-3 w-25">
      <label class="form-label">Form name</label>
      <div class="d-flex gap-2">
        <input
          v-model="formName"
          class="form-control form-control-sm"
          placeholder="e.g. payroll"
          @input="formName = toColumnName(formName)"
        />
        <button class="btn btn-sm btn-primary text-nowrap" @click="addField" :disabled="!formName">
          + Add field
        </button>
        <button class="btn btn-sm btn-success text-nowrap" @click="showExportModal = true" :disabled="!formsPreview.length">
          Export
        </button>
      </div>
    </div>

    <!-- Export Modal -->
    <div v-if="showExportModal" class="modal d-block" style="background:rgba(0,0,0,0.4);">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header">
            <h6 class="modal-title mb-0">Export Tables</h6>
            <button class="btn-close" @click="showExportModal = false"></button>
          </div>
          <div class="modal-body">

            <div class="mb-3">
  <label class="form-label small text-muted">File name</label>
  <div class="input-group input-group-sm">
    <input v-model="exportFilename" class="form-control" placeholder="my_export" />
    <span class="input-group-text">.sql</span>
  </div>
</div>

            <div class="d-flex justify-content-between align-items-center mb-2">
              <small class="text-muted">Select tables to export</small>
              <div class="d-flex gap-2">
                <button class="btn btn-outline-secondary" style="font-size:11px;padding:1px 8px;" @click="selectAll">All</button>
                <button class="btn btn-outline-secondary" style="font-size:11px;padding:1px 8px;" @click="selectNone">None</button>
              </div>
            </div>
            <div v-for="form in formsPreview" :key="form.id" class="form-check mb-1">
              <input
                type="checkbox"
                class="form-check-input"
                :id="`exp_${form.id}`"
                :value="form.id"
                v-model="exportSelected"
              />
              <label class="form-check-label small" :for="`exp_${form.id}`">{{ form.name }}</label>
            </div>
          </div>
          <div class="modal-footer">
            <button class="btn btn-sm btn-outline-secondary" @click="showExportModal = false">Cancel</button>
            <button
              class="btn btn-sm btn-success"
              :disabled="!exportSelected.length"
              @click="runExport"
            >
              Export {{ exportSelected.length === formsPreview.length ? 'All' : `(${exportSelected.length})` }}
            </button>
          </div>
        </div>
      </div>
    </div>

    <div v-for="(field, i) in fields" :key="i" class="border rounded p-2 mb-2">
      <div class="row g-2 align-items-end">
        <div class="col">
          <label class="form-label small text-muted mb-1">Label</label>
          <input v-model="field.field_label" class="form-control form-control-sm" placeholder="Enter your name" />
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Column name</label>
          <input v-model="field.field_name" class="form-control form-control-sm" placeholder="full_name"
            @input="field.field_name = toColumnName(field.field_name)" />
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Type</label>
          <select v-model="field.field_type" class="form-select form-select-sm">
            <option v-for="t in types" :value="t">{{ t }}</option>
          </select>
        </div>
        <div class="col-auto d-flex gap-1">
          <button class="btn btn-sm btn-outline-secondary" :disabled="i === 0" @click="move(i, -1)">↑</button>
          <button class="btn btn-sm btn-outline-secondary" :disabled="i === fields.length - 1" @click="move(i, 1)">↓</button>
          <button class="btn btn-sm btn-outline-danger" @click="fields.splice(i,1)">×</button>
        </div>
      </div>

      <div class="d-flex gap-3 align-items-center mt-2">
        <div class="form-check form-check-sm mb-0">
          <input v-model="field.is_required" type="checkbox" class="form-check-input" :id="`r${i}`" />
          <label class="form-check-label small" :for="`r${i}`">Required</label>
        </div>
        <div class="form-check form-check-sm mb-0">
          <input v-model="field.multi_step" type="checkbox" class="form-check-input" :id="`ms${i}`" />
          <label class="form-check-label small" :for="`ms${i}`">Multi-step</label>
        </div>
        <div v-if="field.multi_step" class="d-flex align-items-center gap-1">
          <label class="small text-muted mb-0">Step</label>
          <input v-model="field.step" type="number" min="1" class="form-control form-control-sm" style="width:60px;" />
        </div>
      </div>

      <div v-if="field.field_type === 'select'" class="mt-2 pt-2 border-top">
        <label class="form-label small text-muted mb-1">Options (comma separated)</label>
        <input v-model="field.options" class="form-control form-control-sm" placeholder="active,inactive" />
      </div>

      <div v-if="field.field_type === 'number'" class="row g-2 mt-2 pt-2 border-top">
        <div class="col">
          <label class="form-label small text-muted mb-1">Min</label>
          <input v-model="field.min" type="number" class="form-control form-control-sm" placeholder="0" />
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Max</label>
          <input v-model="field.max" type="number" class="form-control form-control-sm" placeholder="100" />
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Step</label>
          <input v-model="field.number_step" type="number" class="form-control form-control-sm" placeholder="1" />
        </div>
      </div>

      <div v-if="field.field_type === 'checkbox'" class="mt-2 pt-2 border-top">
        <div class="form-check form-check-sm">
          <input v-model="field.default_checked" type="checkbox" class="form-check-input" :id="`dc${i}`" />
          <label class="form-check-label small" :for="`dc${i}`">Checked by default</label>
        </div>
      </div>

      <div v-if="field.field_type === 'file'" class="row g-2 mt-2 pt-2 border-top">
        <div class="col">
          <label class="form-label small text-muted mb-1">Accepted types</label>
          <input v-model="field.accepted_types" class="form-control form-control-sm" placeholder="image/*,application/pdf" />
        </div>
        <div class="col-3">
          <label class="form-label small text-muted mb-1">Max size (KB)</label>
          <input v-model="field.max_size_kb" type="number" class="form-control form-control-sm" placeholder="2048" />
        </div>
      </div>

      <div v-if="field.field_type === 'relation'" class="row g-2 mt-2 pt-2 border-top">
        <div class="col">
          <label class="form-label small text-muted mb-1">Foreign key column</label>
          <input v-model="field.field_name" class="form-control form-control-sm" placeholder="employee_id"
            @input="field.field_name = toColumnName(field.field_name)" />
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Related table</label>
          <select v-model="field.related_form_id" class="form-select form-select-sm">
            <option value="">Select...</option>
            <option v-for="f in availableForms" :value="f.id">{{ f.name }}</option>
          </select>
        </div>
        <div class="col">
          <label class="form-label small text-muted mb-1">Relation type</label>
          <select v-model="field.relation_type" class="form-select form-select-sm">
            <option value="one_to_one">One to one</option>
            <option value="one_to_many">One to many</option>
            <option value="many_to_many">Many to many</option>
          </select>
        </div>
      </div>

      <div v-if="fields.length > 1" class="row g-2 mt-2 pt-2 border-top align-items-end">
        <div class="col">
          <label class="form-label small text-muted mb-1">Show only when</label>
          <select v-model="field.condition_field" class="form-select form-select-sm">
            <option value="">Always visible</option>
            <option v-for="f in fields.filter((_,j) => j !== i)" :value="f.field_name">
              {{ f.field_label || f.field_name || 'unnamed' }}
            </option>
          </select>
        </div>
        <div class="col" v-if="field.condition_field">
          <label class="form-label small text-muted mb-1">Equals</label>
          <input v-model="field.condition_value" class="form-control form-control-sm" placeholder="value..." />
        </div>
      </div>
    </div>

    <div class="d-flex gap-2 align-items-center mt-3">
      <button class="btn btn-sm btn-dark" @click="saveForm" :disabled="saving || fields.length < 1">
        {{ saving ? 'Saving...' : editingId ? 'Update' : 'Save' }}
      </button>
      <button v-if="editingId" class="btn btn-sm btn-outline-secondary" @click="cancelEdit">Cancel</button>
      <span v-if="saveStatus === 'success'" class="text-success small">{{ editingId ? 'Updated.' : 'Saved.' }}</span>
      <span v-if="saveStatus === 'error'" class="text-danger small">Something went wrong.</span>
    </div>

    <!-- form previewer -->
    <div class="mt-4">
      <h6 class="mb-3">Existing Forms</h6>
      <div v-if="!formsPreview.length" class="text-muted small">No forms yet</div>
      <div v-for="form in formsPreview" :key="form.id" class="border rounded p-3 mb-3">
        <div class="d-flex justify-content-between align-items-center mb-2">
          <div class="fw-bold">{{ form.name }}</div>
          <div class="d-flex gap-2">
            <button class="btn btn-sm btn-outline-primary" @click="editForm(form)">Edit</button>
            <button class="btn btn-sm btn-outline-success" @click="exportForm(form)">Export</button>
            <button class="btn btn-sm btn-outline-danger" @click="deleteForm(form.id)" :disabled="deletingId === form.id">
              {{ deletingId === form.id ? 'Deleting...' : 'Delete' }}
            </button>
          </div>
        </div>
        <table class="table table-sm">
          <thead>
            <tr>
              <th>Label</th>
              <th>Column</th>
              <th>Type</th>
              <th>Required</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="field in form.fields" :key="field.id">
              <td>{{ field.field_label }}</td>
              <td>{{ field.field_name }}</td>
              <td>{{ field.field_type }}</td>
              <td>
                <span v-if="field.is_required" class="badge bg-danger">Yes</span>
                <span v-else class="badge bg-secondary">No</span>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

  </div>
</template>

<script setup>
import { ref, onMounted, inject } from 'vue'
import axios from 'axios'
import Navbar from '@/components/dynamicSchema/navbar.vue'

const axiosInstance = axios.create({
  baseURL: 'https://bushman.ink/api/v2/'
})

const showError   = inject('showError')
const showMessage = inject('showMessage')

const formName        = ref('')
const fields          = ref([])
const availableForms  = ref([])
const saving          = ref(false)
const saveStatus      = ref(null)
const editingId       = ref(null)
const deletingId      = ref(null)
const showExportModal = ref(false)
const exportSelected  = ref([])

const types = ['text','email','number','date','textarea','select','checkbox','file','relation']

const toColumnName = (val) =>
  val.toLowerCase()
     .replace(/[^a-z0-9\s_]/g, '')
     .replace(/\s+/g, '_')

const formsPreview = ref([])

const getForms = async () => {
  const res = await axiosInstance.get('forms')
  availableForms.value = res.data
  formsPreview.value = res.data
}

const clearForm = () => {
  fields.value = []
  formName.value = ''
  editingId.value = null
}

onMounted(() => getForms())

const addField = () => fields.value.push({
  field_label: '', field_name: '', field_type: 'text', is_required: false,
  options: '', accepted_types: '', max_size_kb: '',
  min: '', max: '', number_step: '',
  default_checked: false,
  related_form_id: '', relation_type: 'one_to_many',
  condition_field: '', condition_value: '',
  multi_step: false, step: 1,
})

const move = (i, dir) => {
  const f = fields.value
  const tmp = f[i + dir]
  f[i + dir] = f[i]
  f[i] = tmp
}

const editForm = (form) => {
  editingId.value = form.id
  formName.value = form.name
  fields.value = form.fields.map(f => ({ ...f }))
  saveStatus.value = null
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

const cancelEdit = () => {
  clearForm()
  saveStatus.value = null
}

const saveForm = async () => {
  if (!formName.value) return showError('Form name is required.')
  const invalid = fields.value.find(f => !f.field_label || !f.field_name)
  if (invalid) return showError('All fields need a label and column name.')

  saving.value = true
  saveStatus.value = null
  try {
    if (editingId.value) {
      await axiosInstance.put(`forms/${editingId.value}`, { name: formName.value, fields: fields.value })
    } else {
      await axiosInstance.post('forms', { name: formName.value, fields: fields.value })
    }
    saveStatus.value = 'success'
    await getForms()
    clearForm()
  } catch {
    saveStatus.value = 'error'
  } finally {
    saving.value = false
  }
}

const deleteForm = async (id) => {
  if (!confirm('Delete this form? This cannot be undone.')) return
  deletingId.value = id
  try {
    await axiosInstance.delete(`forms/${id}`)
    showMessage('Form Deleted!')
    await getForms()
  } catch (err) {
    showError(err.response?.data?.message ?? 'Failed to delete form.')
  } finally {
    deletingId.value = null
  }
}

const exportForm = (form) => {
  window.open(`https://bushman.ink/api/v2/forms/${form.id}/export`, '_blank')
}

const selectAll  = () => exportSelected.value = formsPreview.value.map(f => f.id)
const selectNone = () => exportSelected.value = []


const exportFilename = ref('')

const runExport = () => {
  const ids      = exportSelected.value.join(',')
  const filename = exportFilename.value.trim() || null
  const params   = new URLSearchParams({ ids })
  if (filename) params.append('filename', filename)
  window.open(`https://bushman.ink/api/v2/database/export?${params}`, '_blank')
  showExportModal.value = false
  exportSelected.value  = []
  exportFilename.value  = ''
}

</script>